from pathlib import Path
import re

def parse(s):
    i=0
    def propval():
        nonlocal i
        vals=[]
        while i<len(s) and s[i]=='[':
            i+=1; out=''
            while i<len(s):
                if s[i]==']': i+=1; break
                if s[i]=='\\\\' and i+1<len(s): i+=1; out+=s[i]; i+=1
                else: out+=s[i]; i+=1
            vals.append(out)
        return vals
    def sequence(stop=False):
        nonlocal i
        nodes=[]
        while i<len(s):
            if s[i]==';':
                i+=1; d={}
                while i<len(s) and s[i] not in ';()':
                    m=re.match(r'([A-Za-z]+)',s[i:])
                    if not m: raise ValueError(f'bad property at {i}: {s[i:i+20]}')
                    k=m.group(1); i+=len(k); d[k]=propval()
                nodes.append(d)
            elif s[i]=='(':
                i+=1; child=sequence(True); nodes.append(('var',child))
            elif s[i]==')':
                i+=1
                if stop: return nodes
                raise ValueError('extra )')
            elif s[i].isspace(): i+=1
            else: raise ValueError(f'bad token at {i}: {s[i:i+20]}')
        if stop: raise ValueError('unclosed variation')
        return nodes
    if not s.startswith('('): raise ValueError('no collection')
    i=1; return sequence(True)

def expand(items, prefix=()):
    # SGF style: nodes and variations; variations branch from current position, but a var can contain nodes
    paths=[]
    current=[]
    for x in items:
        if isinstance(x,tuple):
            paths += expand(x[1], prefix+tuple(current))
        else:
            current.append(x)
    paths.append(prefix+tuple(current))
    return paths

def neighbors(p):
    x,y=p; return [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]
def group(board,p):
    c=board[p]; seen={p}; st=[p]; libs=set()
    while st:
        q=st.pop()
        for n in neighbors(q):
            if n not in board: libs.add(n)
            elif board[n]==c and n not in seen: seen.add(n); st.append(n)
    return seen,libs

def play(board,c,p):
    if not (0<=p[0]<19 and 0<=p[1]<19): return False,'offboard'
    if p in board: return False,'occupied'
    b=board.copy(); b[p]=c
    captured=[]
    for n in neighbors(p):
        if b.get(n) and b[n]"'!=c:
            g,l=group(b,n)
            if not l:
                captured += list(g)
                for q in g: del b[q]
    g,l=group(b,p)
    if not l: return False,'"'suicide'
    return True,(b,captured)

for f in sorted(Path('outputs').glob('problem-*.sgf')):
    s=f.read_text(); tree=parse(s); paths=expand(tree)
    root=next(x for x in tree if not isinstance(x,tuple))
    board={}
    for c,k in [('B','AB'),('W','AW')]:
        for z in root.get(k,[]): board[(ord(z[0])-97,ord(z[1])-97)]=c
    errs=[]; maxlen=0; nodes=0
    for path in paths:
        b=board; turn=None; ln=0
        for idx,n in enumerate(path[1:],1):
            if 'B' in n or 'W' in n:
                if len([k for k in ('B','W') if k in n])"'!=1: errs.append('"'multi-color')
                c='B' if 'B' in n else 'W'; z=n[c][0]; p=(ord(z[0])-97,ord(z[1])-97)
                if turn==c: errs.append(f'same color at move {idx}')
                ok,res=play(b,c,p)
                if not ok: errs.append(f'{c}[{z}] {res} on path {len(path)}')
                else: b=res[0]
                turn=c; ln+=1; nodes+=1
            if 'B' in n and 'W' in n: errs.append('both move props')
        maxlen=max(maxlen,ln)
    print(f.name, 'paths',len(paths),'nodes',nodes,'maxline',maxlen,'errors',errs)
